// =============================================================================
// dispatch.c — GPU-or-Accelerate routing of BLAS-ABI calls (see dispatch.h)
// =============================================================================

#include "dispatch.h"

#include <errno.h>
#include <limits.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>

#include "dispatch_table.h"   // AB_DISPATCH_BUILTIN[], generated by `make calibrate`

static char trans_class(char t) {
    return t == 'N' || t == 'n' ? 'N' : 'T';
}

bool ab_dispatch_row_covers(const ab_dispatch_row_t *row, char routine,
                            char transA, char transB, int M, int N, int K) {
    return row->routine == routine && row->ta == trans_class(transA) &&
           row->tb == trans_class(transB) && M >= row->m && N >= row->n && K >= row->k;
}

bool ab_dispatch_gpu(const ab_dispatch_config_t *c, char routine,
                     char transA, char transB, int M, int N, int K) {
    if (c->mode == AB_DISPATCH_CPU) return false;
    // Dims below the floor are never profitable (threadgroups underutilized).
    if (M <= c->min_dim || N <= c->min_dim || K <= c->min_dim) return false;
    if (c->mode == AB_DISPATCH_GPU) return true;

    uint64_t crossover = routine == 'd' && c->crossover_flops_real
                       ? c->crossover_flops_real : c->crossover_flops;
    if (crossover)   // in double: M*N*K can exceed 2^64
        return (routine == 'z' ? 8.0 : 2.0) * M * N * K >= (double)crossover;

    for (int i = 0; i < c->nrows; i++)
        if (ab_dispatch_row_covers(&c->rows[i], routine, transA, transB, M, N, K))
            return true;
    return false;
}

static bool parse_trans(const char *tok, char *out) {
    if (strlen(tok) != 1 || !strchr("NTCntc", tok[0])) return false;
    *out = trans_class(tok[0]);
    return true;
}

static bool parse_min(const char *tok, int *out) {
    char *end;
    errno = 0;
    long v = strtol(tok, &end, 10);
    if (errno || *end || end == tok || v < 0 || v > INT_MAX) return false;
    *out = (int)v;
    return true;
}

int ab_dispatch_parse_row(const char *line, ab_dispatch_row_t *row) {
    char buf[256], *tok[6], *save = NULL;
    int n = 0;
    snprintf(buf, sizeof buf, "%s", line);
    buf[strcspn(buf, "#\r\n")] = '\0';
    for (char *t = strtok_r(buf, " \t", &save); t; t = strtok_r(NULL, " \t", &save)) {
        if (n == 6) return -1;
        tok[n++] = t;
    }
    if (n == 0) return 0;
    if (n != 6) return -1;

    ab_dispatch_row_t r;
    if (!strcasecmp(tok[0], "dgemm")) r.routine = 'd';
    else if (!strcasecmp(tok[0], "zgemm")) r.routine = 'z';
    else return -1;
    if (!parse_trans(tok[1], &r.ta) || !parse_trans(tok[2], &r.tb) ||
        !parse_min(tok[3], &r.m) || !parse_min(tok[4], &r.n) || !parse_min(tok[5], &r.k))
        return -1;
    *row = r;
    return 1;
}

bool ab_dispatch_load_table(ab_dispatch_config_t *c, const char *path,
                            char *err, size_t err_len) {
    FILE *f = fopen(path, "r");
    if (!f) {
        snprintf(err, err_len, "%s", strerror(errno));
        return false;
    }
    ab_dispatch_row_t rows[AB_DISPATCH_MAX_ROWS];
    char line[256];
    int nrows = 0, lineno = 0;
    const char *why = NULL;
    while (!why && fgets(line, sizeof line, f)) {
        lineno++;
        // A line longer than the buffer is allowed only as a comment.
        bool whole = strchr(line, '\n') || feof(f);
        bool comment = line[strspn(line, " \t")] == '#';
        for (int ch = 0; !whole && ch != '\n' && ch != EOF; ) ch = fgetc(f);
        ab_dispatch_row_t r;
        int got = whole || comment ? ab_dispatch_parse_row(line, &r) : -1;
        if (got < 0)
            why = "expected '<dgemm|zgemm> <N|T|C> <N|T|C> <min_M> <min_N> <min_K>'";
        else if (got && nrows == AB_DISPATCH_MAX_ROWS)
            why = "too many rows";
        else if (got)
            rows[nrows++] = r;
    }
    if (!why && ferror(f)) why = "read error";
    fclose(f);
    if (why) {
        snprintf(err, err_len, "line %d: %s", lineno, why);
        return false;
    }
    memcpy(c->rows, rows, (size_t)nrows * sizeof rows[0]);
    c->nrows = nrows;
    return true;
}

static uint64_t env_flops(const char *name) {
    const char *s = getenv(name);
    return s && *s ? strtoull(s, NULL, 10) : 0;
}

void ab_dispatch_config_from_env(ab_dispatch_config_t *c) {
    memset(c, 0, sizeof *c);
    const char *mode = getenv("AB_MODE");
    c->mode = mode && (mode[0] == 'c' || mode[0] == 'C') ? AB_DISPATCH_CPU
            : mode && (mode[0] == 'g' || mode[0] == 'G') ? AB_DISPATCH_GPU
            : AB_DISPATCH_AUTO;

    const char *min_dim = getenv("AB_MIN_GPU_DIM");
    c->min_dim = min_dim && *min_dim ? atoi(min_dim) : AB_DISPATCH_DEFAULT_MIN_DIM;
    if (c->min_dim < 0) c->min_dim = AB_DISPATCH_DEFAULT_MIN_DIM;

    c->crossover_flops = env_flops("AB_CROSSOVER_FLOPS");
    c->crossover_flops_real = env_flops("AB_CROSSOVER_FLOPS_REAL");

    for (const ab_dispatch_row_t *r = AB_DISPATCH_BUILTIN;
         r->routine && c->nrows < AB_DISPATCH_MAX_ROWS; r++)
        c->rows[c->nrows++] = *r;

    const char *table = getenv("AB_DISPATCH_TABLE");
    char err[160];
    if (table && *table && !ab_dispatch_load_table(c, table, err, sizeof err))
        fprintf(stderr, "apple-bottom: AB_DISPATCH_TABLE=%s: %s; using the built-in table\n",
                table, err);
}

static ab_dispatch_config_t g_config;
static pthread_once_t g_config_once = PTHREAD_ONCE_INIT;

static void load_config(void) { ab_dispatch_config_from_env(&g_config); }

bool ab_dispatch_route_gpu(char routine, char transA, char transB, int M, int N, int K) {
    pthread_once(&g_config_once, load_config);
    return ab_dispatch_gpu(&g_config, routine, transA, transB, M, N, K);
}
